// console.log(mqtt.connect)
const plugins = {
  client: null,
  mqttStore: null,
  async install(app_arg, options) {
    this.mqttStore = useMqttStore();
    this.userStore = useUserStore();
    app_arg.config.globalProperties.$mqtt = this;
    // uni.$mqtt = this
  },
  handShaking() {
    console.log("handShaking", mqtt);
    if (this.client && this.isConnected()) {
      this.disconnect();
    }
    const { brokerUrl, username, password, gatewayMac } = this.mqttStore;
    const { run_version } = this.userStore;
    try {
      let option = {
        connectTimeout: 40000,
        keepalive: 30,
        reconnectPeriod: 5000,
        clientId: "rom" + Math.random() * 100,
        clean: true,
        reconnect: true, // 连接中断后会重新连接
        username: username,
        password: password,
      };
      this.client = mqtt.connect(brokerUrl, option); // APP
    } catch (e) {
      console.log("eeeeeeeeeeeee");
      console.log(e);
      if (this.mqttStore) {
        this.mqttStore.state = 0;
      }
      return;
    }
    // mqtt连接
    this.client.on("connect", () => {
      // EventBus.post(EventBus.MQTT_EVENT.CONNECT_SUCCESS)
      console.log("连接成功:", this.mqttStore);
      if (this.mqttStore) {
        this.mqttStore.state = 1;
        showNotify({ type: "success", message: `网络连接成功` });
        this.subscribe(`post/state`, 0);

        // 调试
        // this.publish(`${username}/${gatewayMac}/run_version`, "0", 0);
        // 跳转
        // this.mqttStore.tabValue = 0;
      }
    });
    // 接收消息处理
    this.client.on("message", (topic, message) => {
      console.log("收到来自", topic, "的消息");
      let msg = message.toString();
      console.log(msg); // 0_1/2/3
      let temp = msg.split("_");
      if (temp[0] === this.mqttStore.userId) {
        console.log(temp[1]);
        if (["1", "2", "3"].includes(temp[1])) {
          this.mqttStore.setDoorState(Number(temp[1]));
          showNotify({
            type: "success",
            message: `${
              (temp[1] === "1" && "已停止") ||
              (temp[1] === "3" && "关闭中") ||
              (temp[1] === "2" && "打开中")
            }`,
          });
        } else {
          showNotify({
            message:
              (temp[1] === "401" && "登陆过期") ||
              (temp[1] === "500" && "参数错误") ||
              (temp[1] === "502" && "系统繁忙,稍后再试") ||
              "未知错误",
          });
        }
        this.mqttStore.setBtnLoading(false);
      }
      if (this.mqttStore);
    });
    // 断开发起重连
    this.client.on("reconnect", () => {
      console.log("正在重连:");
      if (this.mqttStore) {
        this.mqttStore.state = -1;
      }
    });
    // 断开链接
    this.client.on("disconnect", () => {
      // EventBus.post(EventBus.MQTT_EVENT.CONNECT_LOST)
      console.log("断开链接:");
      if (this.mqttStore) {
        this.mqttStore.state = 0;
      }
    });
    // 链接异常处理
    this.client.on("error", (error) => {
      // EventBus.post(EventBus.MQTT_EVENT.CONNECT_FAILED)
      console.log("连接失败:", error);
      if (this.mqttStore) {
        this.mqttStore.state = 0;
      }
      // uni.redirectTo({
      //   url: `/pages/login/index`,
      // });
    });
  },
  subscribe(topic, qos) {
    this.client.subscribe(topic, { qos: qos }, (error) => {
      if (!error) {
        console.log("订阅成功:" + topic);
      } else {
        console.log("订阅失败");
      }
    });
  },
  publish(topic, msg, qos) {
    this.client.publish(topic, msg, { qos: qos }, (error) => {
      if (!error) {
        console.log("发布:" + topic);
        console.log("消息:" + msg);
        if (this.mqttStore);
      } else {
        console.log("发布失败");
      }
    });
  },
  unSubscribe(topic) {
    this.client.unSubscribe(topic, (error) => {
      if (!error) {
        console.log("取消订阅成功");
      } else {
        console.log("取消订阅失败");
      }
    });
  },

  disconnect() {
    if (this.client) {
      console.log("退出连接");
      this.client.end();
      this.client = null;
    }
  },
  isConnected() {
    let ret = false;
    if (this.client && this.client.connected) {
      ret = true;
    }
    return ret;
  },
};

